import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1787777736000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>CALIBRE_WEB_URL</code></td><td>yes</td><td>Root URL of the Calibre-Web instance, e.g. <code>https://books.example.com</code>. The <code>/opds</code> path is appended automatically. Subpath installations (<code>https://host.example/calibre</code>) work.</td></tr><tr><td><code>CALIBRE_WEB_USERNAME</code></td><td>yes¹</td><td>Username of the Calibre-Web account. The OPDS feed authenticates with the normal web login via HTTP Basic auth.</td></tr><tr><td><code>CALIBRE_WEB_PASSWORD</code></td><td>yes¹</td><td>Password of that account (the web login password — Calibre-Web has no separate API tokens).</td></tr><tr><td><code>CALIBRE_WEB_INSECURE_TLS</code></td><td>no</td><td><code>true</code> to accept self-signed certificates. Scoped to the configured host; never disables TLS validation process-wide.</td></tr></tbody></table><p>¹ The credentials count as a pair: leave <strong>both</strong> unset for an instance that allows anonymous browsing; setting only one of them is a configuration error.</p><h2 id="behaviour-without-configuration" tabindex="-1">Behaviour without configuration <a class="header-anchor" href="#behaviour-without-configuration" aria-label="Permalink to “Behaviour without configuration”">​</a></h2><p>The server starts and lists its tools even with nothing set — registries and sandbox inspectors can introspect it. Every tool call then fails with setup instructions instead of reaching any host.</p><h2 id="validation-at-startup" tabindex="-1">Validation at startup <a class="header-anchor" href="#validation-at-startup" aria-label="Permalink to “Validation at startup”">​</a></h2><ul><li>Fatal: an unparseable URL, a non-http(s) scheme, or credentials embedded in the URL (<code>https://user:pass@host</code> — they would end up in logs; use the dedicated variables).</li><li>Warning: plain <code>http://</code> to a non-loopback host (the password would cross the network unencrypted), or only one of the two credential variables set.</li><li><code>CALIBRE_WEB_PASSWORD</code> is deleted from <code>process.env</code> immediately after being read.</li></ul><h2 id="narrowing-the-tool-list" tabindex="-1">Narrowing the tool list <a class="header-anchor" href="#narrowing-the-tool-list" aria-label="Permalink to “Narrowing the tool list”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>CALIBRE_WEB_ALLOW_TOOLS</code></td><td>no</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register</td></tr><tr><td><code>CALIBRE_WEB_DENY_TOOLS</code></td><td>no</td><td>Same syntax; subtracted from whatever the allow list left</td></tr></tbody></table><p>Both are comma-separated. Each entry is either an exact tool name or a prefix with a single trailing <code>*</code>. Entries are trimmed and matched case-insensitively; empty entries are ignored, and a value that is empty or only whitespace counts as unset — <code>CALIBRE_WEB_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;. <code>essential</code> is recognised only in the allow list, and selects <code>search_books</code>, <code>list_books</code>, <code>list_shelves</code>, <code>get_shelf_books</code>, <code>get_stats</code>.</p><p><strong>An entry that matches no tool aborts startup</strong>, naming the entry and listing the valid names, as does a malformed pattern such as <code>*_x</code> or <code>list_*_x</code>. The alternative — ignoring the entry — leaves a tool missing from <code>tools/list</code> with nothing pointing at the cause. If both lists together remove everything, the server refuses to start rather than offering an empty tool list.</p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};